INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-179',unit_id,'quiz-topic-neuro-ap1','Que ossos formam a fossa craniana média?',NULL,'A fossa craniana média é formada pelos ossos <strong>esfenóide e temporal</strong> e suporta os lobos temporais. É limitada anteriormente pelas faces posteriores das asas menor e maior do esfenóide, posteriormente pelo bordo superior da porção petrosa do temporal, lateralmente pela parte escamosa do temporal e pela asa maior do esfenóide, e medialmente pela face lateral do corpo do esfenóide, incluindo o sulco carotídeo, sela turca e dorso da sela.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
