INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-182',unit_id,'quiz-topic-neuro-ap1','Que abertura comunica a fossa craniana média com a órbita?',NULL,'<strong>A fossa craniana média comunica com as órbitas pelas fissuras orbitárias superiores</strong>. Cada fissura é limitada superiormente pela asa menor, inferiormente pela asa maior e medialmente pelo corpo do esfenóide e pelo pilar óptico.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-182-answer','quiz-neuro-ap1-182','Fissura orbitária superior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-182-incorrect','quiz-neuro-ap1-182','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-183',unit_id,'quiz-topic-neuro-ap1','Que asa limita superiormente a fissura orbitária superior?',NULL,'A fossa craniana média comunica com as órbitas pelas fissuras orbitárias superiores. Cada fissura é limitada <strong>superiormente pela asa menor</strong> e inferiormente pela asa maior; medialmente relaciona-se com o corpo do esfenóide e o pilar óptico.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-183-answer','quiz-neuro-ap1-183','Asa menor do esfenóide',1,1);
