INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-185',unit_id,'quiz-topic-neuro-ap1','Que três nervos motores oculares atravessam a fissura orbitária superior?',NULL,'Atravessam-na os nervos <strong>oculomotor, troclear e abducente</strong>; os ramos lacrimal, frontal e nasociliar da divisão oftálmica do trigémio; fibras simpáticas pós-ganglionares do plexo carotídeo interno; as veias oftálmicas superior e inferior; o ramo orbitário da artéria meníngea média; e o ramo recorrente da artéria lacrimal. A região central da base craniana entre as duas fossas médias é formada pelo corpo do esfenóide, que contém os seios esfenoidais.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-185-answer','quiz-neuro-ap1-185','Oculomotor, troclear e abducente',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-185-incorrect','quiz-neuro-ap1-185','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-186',unit_id,'quiz-topic-neuro-ap1','De que divisão do trigémio derivam os ramos que atravessam a fissura orbitária superior?',NULL,'Pela fissura orbitária superior passam os nervos oculomotor, troclear e abducente e os ramos lacrimal, frontal e nasociliar, todos derivados da <strong>divisão oftálmica do nervo trigémio</strong>.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-186-answer','quiz-neuro-ap1-186','Divisão oftálmica',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-186-incorrect','quiz-neuro-ap1-186','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-187',unit_id,'quiz-topic-neuro-ap1','Que depressão do esfenóide aloja a hipófise?',NULL,'A região central da base craniana entre as duas fossas médias é formada pelo corpo do esfenóide, que contém os seios esfenoidais. A superfície superior do corpo é profundamente côncava e aloja a hipófise; por isso, esta depressão é a <strong>fossa hipofisária</strong>, parte da sela turca. A proximidade da sela aos seios esfenoidais explica a via cirúrgica transesfenoidal para acesso à hipófise.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-187-answer','quiz-neuro-ap1-187','Fossa hipofisária',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-187-incorrect','quiz-neuro-ap1-187','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-188',unit_id,'quiz-topic-neuro-ap1','Que estrutura óssea contém a fossa hipofisária?',NULL,'A região central da base craniana entre as duas fossas médias é formada pelo corpo do esfenóide, que contém os seios esfenoidais. A superfície superior do corpo é profundamente côncava e aloja a hipófise; por isso, esta depressão é a fossa hipofisária, parte da <strong>sela turca</strong>. A proximidade da sela aos seios esfenoidais explica a via cirúrgica transesfenoidal para acesso à hipófise.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
