INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-189',unit_id,'quiz-topic-neuro-ap1','Que acidente forma o bordo anterior da sela turca?',NULL,'A proximidade da sela aos seios esfenoidais explica a via cirúrgica transesfenoidal para acesso à hipófise. O bordo anterior da sela é o <strong>tubérculo da sela</strong>, contínuo anteriormente com o sulco pré-quiasmático. O limite posterior é uma lâmina óssea vertical, o dorso da sela, cujos ângulos superolaterais se expandem nas apófises clinóides posteriores.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-189-answer','quiz-neuro-ap1-189','Tubérculo da sela',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-189-incorrect','quiz-neuro-ap1-189','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-190',unit_id,'quiz-topic-neuro-ap1','Que lâmina forma o limite posterior da sela turca?',NULL,'O bordo anterior da sela é o tubérculo da sela, contínuo anteriormente com o sulco pré-quiasmático. O limite posterior é uma lâmina óssea vertical, o <strong>dorso da sela</strong>, cujos ângulos superolaterais se expandem nas apófises clinóides posteriores. O diafragma da sela, uma prega de dura-máter, fixa-se às apófises clinóides anteriores e posteriores e forma o teto da fossa hipofisária.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-190-answer','quiz-neuro-ap1-190','Dorso da sela',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-190-incorrect','quiz-neuro-ap1-190','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-191',unit_id,'quiz-topic-neuro-ap1','Que apófises se projetam dos ângulos superolaterais do dorso da sela?',NULL,'O bordo anterior da sela é o tubérculo da sela, contínuo anteriormente com o sulco pré-quiasmático. O limite posterior é uma lâmina óssea vertical, o dorso da sela, cujos ângulos superolaterais se expandem nas <strong>apófises clinóides posteriores</strong>. O diafragma da sela, uma prega de dura-máter, fixa-se às apófises clinóides anteriores e posteriores e forma o teto da fossa hipofisária.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
