INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-192',unit_id,'quiz-topic-neuro-ap1','Que seio venoso se situa lateralmente à fossa hipofisária?',NULL,'O diafragma da sela, uma prega de dura-máter, fixa-se às apófises clinóides anteriores e posteriores e forma o teto da fossa hipofisária. O <strong>seio cavernoso</strong> situa-se lateralmente à fossa. Na face lateral do corpo do esfenóide existe um sulco carotídeo pouco profundo, relacionado com a artéria carótida interna quando esta ascende do canal carotídeo e percorre o seio cavernoso.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
