INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-194',unit_id,'quiz-topic-neuro-ap1','Que apófise clinóide pode ser inconstante?',NULL,'A apófise clinóide anterior dá inserção ao ligamento petroclinóide anterior, que participa no bordo livre da tenda do cerebelo, e ao ligamento interclinóide, situado entre as apófises clinóides anterior e posterior. A <strong>apófise clinóide média</strong> nasce do corpo do esfenóide no bordo anterolateral da sela turca e pode ligar-se à apófise clinóide anterior por uma ponte óssea resultante da ossificação do ligamento carótico-clinóide. O buraco ou anel carótico-clinóide assim formado circunda o segmento paraclinóide da artéria carótida interna (Fernandez-Miranda et al., 2012).<p><small>Gray’s Anatomy, 42.ª ed., pp. 566–567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-194-answer','quiz-neuro-ap1-194','Apófise clinóide média',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-194-incorrect','quiz-neuro-ap1-194','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-195',unit_id,'quiz-topic-neuro-ap1','Entre que apófises se forma o anel carótico-clinóide?',NULL,'As <strong>apófises clinóides anterior e média</strong> podem unir-se por uma ponte óssea e formar o buraco ou anel carótico-clinóide, que circunda a região paraclinóide da artéria carótida interna. A apófise clinóide média é variável.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, p. 666.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-195-answer','quiz-neuro-ap1-195','Clinóides anterior e média',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-195-incorrect','quiz-neuro-ap1-195','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-196',unit_id,'quiz-topic-neuro-ap1','Que artéria é circundada pelo anel carótico-clinóide?',NULL,'A apófise clinóide média nasce do corpo do esfenóide no bordo anterolateral da sela turca e pode ligar-se à apófise clinóide anterior por uma ponte óssea resultante da ossificação do ligamento carótico-clinóide. O buraco ou anel carótico-clinóide assim formado circunda o segmento paraclinóide da <strong>artéria carótida interna</strong> (Fernandez-Miranda et al., 2012). As apófises clinóides anterior e posterior estão constantemente presentes, ao contrário da apófise clinóide média, que é variável.<p><small>Gray’s Anatomy, 42.ª ed., pp. 566–567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-196-answer','quiz-neuro-ap1-196','Artéria carótida interna',1,1);
