INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-197',unit_id,'quiz-topic-neuro-ap1','Qual é o mais anterior dos três buracos constantes da asa maior do esfenóide?',NULL,'A asa maior do esfenóide apresenta três buracos relativamente constantes. <strong>O buraco redondo é o mais anterior</strong>; posteriormente encontra-se o buraco oval e o buraco espinhoso situa-se posterolateralmente ao oval.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-197-answer','quiz-neuro-ap1-197','Buraco redondo',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-197-incorrect','quiz-neuro-ap1-197','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-198',unit_id,'quiz-topic-neuro-ap1','Qual é o buraco da asa maior imediatamente posterior ao redondo?',NULL,'O buraco redondo, situado imediatamente abaixo da extremidade medial da fissura orbitária superior, dirige-se anteriormente para a região medial da fissura orbitária inferior e abre na fossa pterigopalatina; transmite o nervo maxilar, segunda divisão do trigémio. Posteriormente ao buraco redondo encontra-se o <strong>buraco oval</strong>, que transmite o nervo mandibular, terceira divisão do trigémio. O buraco espinhoso situa-se posterolateralmente ao buraco oval e transmite a artéria e veias meníngeas médias, que sulcam o pavimento e a parede lateral da fossa craniana média.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-198-answer','quiz-neuro-ap1-198','Buraco oval',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-198-incorrect','quiz-neuro-ap1-198','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-199',unit_id,'quiz-topic-neuro-ap1','Qual é o buraco posterolateral ao oval?',NULL,'Posteriormente ao buraco redondo encontra-se o buraco oval, que transmite o nervo mandibular, terceira divisão do trigémio. O <strong>buraco espinhoso</strong> situa-se posterolateralmente ao buraco oval e transmite a artéria e veias meníngeas médias, que sulcam o pavimento e a parede lateral da fossa craniana média. Os buracos oval e espinhoso abrem inferiormente na fossa infratemporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-199-answer','quiz-neuro-ap1-199','Buraco espinhoso',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-199-incorrect','quiz-neuro-ap1-199','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-200',unit_id,'quiz-topic-neuro-ap1','Que nervo atravessa o buraco redondo?',NULL,'O buraco redondo, situado imediatamente abaixo da extremidade medial da fissura orbitária superior, dirige-se anteriormente para a região medial da fissura orbitária inferior e abre na fossa pterigopalatina; transmite o <strong>nervo maxilar</strong>, segunda divisão do trigémio. Posteriormente ao buraco redondo encontra-se o buraco oval, que transmite o nervo mandibular, terceira divisão do trigémio.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
