INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-204',unit_id,'quiz-topic-neuro-ap1','Onde abrem inferiormente os buracos oval e espinhoso?',NULL,'O buraco espinhoso situa-se posterolateralmente ao buraco oval e transmite a artéria e veias meníngeas médias, que sulcam o pavimento e a parede lateral da fossa craniana média. Os buracos oval e espinhoso abrem inferiormente na <strong>fossa infratemporal</strong>. O bordo superior da porção petrosa do temporal separa as fossas cranianas média e posterior e é sulcado pelo seio petroso superior.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
