INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-205',unit_id,'quiz-topic-neuro-ap1','Que impressão na face anterior petrosa aloja o gânglio trigeminal?',NULL,'O bordo superior da porção petrosa do temporal separa as fossas cranianas média e posterior e é sulcado pelo seio petroso superior. A <strong>impressão trigeminal</strong>, que aloja o gânglio trigeminal, encontra-se na face anterior da porção petrosa junto do ápice. Uma incisura trigeminal lisa conduz a esta impressão e situa-se no bordo superior petroso, anteromedialmente ao sulco do seio petroso superior.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-205-answer','quiz-neuro-ap1-205','Impressão trigeminal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-205-incorrect','quiz-neuro-ap1-205','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-206',unit_id,'quiz-topic-neuro-ap1','Que sulco percorre o bordo superior petroso?',NULL,'A impressão trigeminal, que aloja o gânglio trigeminal, encontra-se na face anterior da porção petrosa junto do ápice. Uma incisura trigeminal lisa conduz a esta impressão e situa-se no bordo superior petroso, anteromedialmente ao <strong>sulco do seio petroso superior</strong>. Neste nível, o nervo trigémio passa da fossa posterior para a média e separa o seio petroso superior do osso subjacente.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-206-answer','quiz-neuro-ap1-206','Sulco do seio petroso superior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-206-incorrect','quiz-neuro-ap1-206','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-207',unit_id,'quiz-topic-neuro-ap1','Que nervo passa habitualmente sob o ligamento petroesfenoidal?',NULL,'O <strong>nervo abducente</strong> curva-se acentuadamente sobre o bordo petroso superior e medialmente sobre o bordo lateral do dorso da sela ou apófise petrosa do esfenóide, passando habitualmente por baixo do ligamento petroesfenoidal para entrar no seio cavernoso (Ozveren et al., 2002). O espaço interdural delimitado superiormente pelo ligamento petroesfenoidal, inferiormente pela apófise petrosa, lateralmente pelo ápice petroso e medialmente pelo dorso da sela corresponde ao canal de Dorello.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-207-answer','quiz-neuro-ap1-207','Nervo abducente',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-207-incorrect','quiz-neuro-ap1-207','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-208',unit_id,'quiz-topic-neuro-ap1','Que canal interdural contém o nervo abducente junto ao ápice petroso?',NULL,'O nervo abducente curva-se acentuadamente sobre o bordo petroso superior e medialmente sobre o bordo lateral do dorso da sela ou apófise petrosa do esfenóide, passando habitualmente por baixo do ligamento petroesfenoidal para entrar no seio cavernoso (Ozveren et al., 2002). O espaço interdural delimitado superiormente pelo ligamento petroesfenoidal, inferiormente pela apófise petrosa, lateralmente pelo ápice petroso e medialmente pelo dorso da sela corresponde ao <strong>canal de Dorello</strong>. Também é descrito como confluência venosa petroclival, por conter sangue proveniente dos seios petrosos inferior e superior, seio cavernoso e plexo basilar.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-208-answer','quiz-neuro-ap1-208','Canal de Dorello',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-208-incorrect','quiz-neuro-ap1-208','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-209',unit_id,'quiz-topic-neuro-ap1','Que nervo emerge pelo hiato facial na face anterior petrosa?',NULL,'Também é descrito como confluência venosa petroclival, por conter sangue proveniente dos seios petrosos inferior e superior, seio cavernoso e plexo basilar. Lateralmente à impressão trigeminal, um sulco estreito dirige-se posterolateralmente para o hiato do <strong>nervo petroso maior</strong>; ainda mais lateralmente localizam-se o hiato e sulco do nervo petroso menor (Kakizawa et al., 2007). Posterolateralmente ao hiato facial, uma proeminência arredondada, a eminência arqueada, é produzida pelo canal semicircular superior subjacente.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-209-answer','quiz-neuro-ap1-209','Nervo petroso maior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-209-incorrect','quiz-neuro-ap1-209','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-210',unit_id,'quiz-topic-neuro-ap1','Que nervo emerge pelo hiato situado mais lateralmente?',NULL,'Também é descrito como confluência venosa petroclival, por conter sangue proveniente dos seios petrosos inferior e superior, seio cavernoso e plexo basilar. Lateralmente à impressão trigeminal, um sulco estreito dirige-se posterolateralmente para o hiato do nervo petroso maior; ainda mais lateralmente localizam-se o hiato e sulco do <strong>nervo petroso menor</strong> (Kakizawa et al., 2007). Posterolateralmente ao hiato facial, uma proeminência arredondada, a eminência arqueada, é produzida pelo canal semicircular superior subjacente.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
