INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-211',unit_id,'quiz-topic-neuro-ap1','Que estrutura subjacente eleva habitualmente a eminência arqueada?',NULL,'Na face anterior da porção petrosa do temporal, a eminência arqueada é habitualmente elevada pelo <strong>canal semicircular superior</strong>, embora a proeminência óssea não esteja necessariamente situada diretamente sobre o canal.<p><small>Gray’s Anatomy, 42.ª ed., cap. 42, p. 737.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-211-answer','quiz-neuro-ap1-211','Canal semicircular superior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-211-incorrect','quiz-neuro-ap1-211','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-212',unit_id,'quiz-topic-neuro-ap1','Que estrutura óssea delgada separa ouvido médio e fossa craniana média?',NULL,'Na petrosectomia anterior, esta porção óssea é removida para permitir acesso à fossa craniana posterior a partir da fossa média (Kawase et al., 1985). A superfície lateral da porção petrosa do temporal é formada pelo <strong>tegmen tympani</strong>, uma lâmina óssea delgada que separa a cavidade timpânica ou ouvido médio da fossa craniana média. O aumento crónico da pressão intracraniana pode provocar erosão do tegmen e otorreia espontânea de líquido cefalorraquidiano.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-212-answer','quiz-neuro-ap1-212','Tegmen tympani',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-212-incorrect','quiz-neuro-ap1-212','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-213',unit_id,'quiz-topic-neuro-ap1','Que estrutura forma o teto do antro mastoideu?',NULL,'O aumento crónico da pressão intracraniana pode provocar erosão do tegmen e otorreia espontânea de líquido cefalorraquidiano. A parte posterior do tegmen forma o teto do antro mastoideu, lateralmente à eminência arqueada, e também se designa <strong>tegmen mastoideum</strong>. Em crânios jovens pode observar-se lateralmente uma sutura petroescamosa, obliterada no adulto.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-213-answer','quiz-neuro-ap1-213','Tegmen mastoideum',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-213-incorrect','quiz-neuro-ap1-213','Resposta não correspondente',2,0);
